function pickWeighted(rng: Rng, table: Array<[string, number]>, fallback: string): string {
  const total = table.reduce((s, [, w]) => s + w, 0);
  let roll = rng.float() * total;
  for (const [nat, w] of table) {
    roll -= w;
    if (roll <= 0) return nat;
  }
  return fallback;
}

