export function pickNat(rng: Rng, clubId: string, league?: LeagueKind, country?: string): string {
  const table = NAT_WEIGHTS[clubId];
  if (table) return pickWeighted(rng, table, "ITA");
  if (country && COUNTRY_NATS[country]) {
    const cleaned = COUNTRY_NATS[country]!.filter(([, w]) => w > 0);
    return pickWeighted(rng, cleaned, country);
  }
  if (league === "premier") return pickWeighted(rng, PREMIER_NATS, "ENG");
  if (league === "laliga") return pickWeighted(rng, LALIGA_NATS, "ESP");
  if (league === "bundesliga") return pickWeighted(rng, BUNDESLIGA_NATS, "GER");
  if (league === "ligue1") return pickWeighted(rng, LIGUE1_NATS, "FRA");
  if (league === "argentina") return pickWeighted(rng, COUNTRY_NATS.ARG!, "ARG");
  if (league === "conmebol") return pickWeighted(rng, COUNTRY_NATS.BRA!, "BRA");
  if (league === "europe") return pickWeighted(rng, COUNTRY_NATS.POR!, "POR");
  return pickWeighted(rng, NAT_WEIGHTS.default!, "ITA");
}

